{"command":"mkdir -p /tmp/build; cd /workspace; mkdir -p src; cat > src/cmatrix.c <<'EOF'
/*
 * Matrix-style "digital rain" for the terminal.
 * Reimplementation written from observed behaviour.
 */
#include <errno.h>
#include <fcntl.h>
#include <ncurses.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <sys/ioctl.h>
#include <termios.h>
#include <time.h>
#include <unistd.h>

#define CM_VERSION "2.0"
#define CM_BUILD_TIME "22:13:51"
#define CM_BUILD_DATE "Jun 11 2026"

typedef struct cell {
    int val;
    bool is_head;
} cell;

static cell **grid = NULL;
static int *stream_len = NULL;
static int *gap_left = NULL;
static int *speed = NULL;

static volatile sig_atomic_t pending_signal = 0;

static int opt_console = 0;
static int opt_xwindow = 0;
static int opt_lock = 0;
static int delay = 4;

static void restore_terminal(void)
{
    curs_set(1);
    clear();
    refresh();
    resetty();
    endwin();
}

static void finish(void)
{
    restore_terminal();
    exit(0);
}

static void die(const char *fmt, ...)
{
    va_list ap;

    restore_terminal();
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);
    exit(0);
}

static void print_usage(void)
{
    printf(" Usage: cmatrix -[abBcfhlsmVxk] [-u delay] [-C color] [-t tty] [-M message]\n");
    printf(" -a: Asynchronous scroll\n");
    printf(" -b: Bold characters on\n");
    printf(" -B: All bold characters (overrides -b)\n");
    printf(" -c: Use Japanese characters as seen in the original matrix. Requires appropriate fonts\n");
    printf(" -f: Force the linux $TERM type to be on\n");
    printf(" -l: Linux mode (uses matrix console font)\n");
    printf(" -L: Lock mode (can be closed from another terminal)\n");
    printf(" -o: Use old-style scrolling\n");
    printf(" -h: Print usage and exit\n");
    printf(" -n: No bold characters (overrides -b and -B, default)\n");
    printf(" -s: \"Screensaver\" mode, exits on first keystroke\n");
    printf(" -x: X window mode, use if your xterm is using mtx.pcf\n");
    printf(" -V: Print version information and exit\n");
    printf(" -M [message]: Prints your message in the center of the screen. Overrides -L's default message.\n");
    printf(" -u delay (0 - 10, default 4): Screen update delay\n");
    printf(" -C [color]: Use this color for matrix (default green)\n");
    printf(" -r: rainbow mode\n");
    printf(" -m: lambda mode\n");
    printf(" -k: Characters change while scrolling. (Works without -o opt.)\n");
    printf(" -t [tty]: Set tty to use\n");
}

static void print_version(void)
{
    printf(" CMatrix version %s (compiled %s, %s)\n", CM_VERSION, CM_BUILD_TIME, CM_BUILD_DATE);
    printf("Email: abishekvashok@gmail.com\n");
    printf("Web: https://github.com/abishekvashok/cmatrix\n");
}

static void *xalloc(size_t n)
{
    void *p = malloc(n);
    if (p == NULL)
        die("cmatrix: malloc: out of memory\n");
    return p;
}

static void setup_grid(void)
{
    int r, c;

    if (grid != NULL) {
        free(grid[0]);
        free(grid);
    }
    grid = xalloc(sizeof(cell *) * (LINES + 1));
    grid[0] = xalloc(sizeof(cell) * (LINES + 1) * COLS);
    for (r = 1; r <= LINES; r++)
        grid[r] = grid[r - 1] + COLS;

    free(stream_len);
    stream_len = xalloc(COLS * sizeof(int));
    free(gap_left);
    gap_left = xalloc(COLS * sizeof(int));
    free(speed);
    speed = xalloc(COLS * sizeof(int));

    for (r = 0; r <= LINES; r++)
        for (c = 0; c <= COLS - 1; c += 2)
            grid[r][c].val = -1;

    for (c = 0; c <= COLS - 1; c += 2) {
        gap_left[c] = (int)rand() % LINES + 1;
        stream_len[c] = (int)rand() % (LINES - 3) + 3;
        grid[1][c].val = ' ';
        speed[c] = (int)rand() % 3 + 1;
    }
}

static void on_signal(int sig)
{
    pending_signal = sig;
}

static void handle_resize(void)
{
    char *name;
    int fd;
    struct winsize ws;

    name = ttyname(0);
    if (!name)
        return;
    fd = open(name, O_RDWR);
    if (fd == -1)
        return;
    if (ioctl(fd, TIOCGWINSZ, &ws) == -1)
        return;

    COLS = ws.ws_col;
    LINES = ws.ws_row;
    if (LINES < 10)
        LINES = 10;
    if (COLS < 10)
        COLS = 10;

    resizeterm(LINES, COLS);
    if (wresize(stdscr, LINES, COLS) == ERR)
        die("Cannot resize window!");

    setup_grid();
    clear();
    refresh();
}

int main(int argc, char *argv[])
{
    int r, top, bottom, opt, key;
    int c = 0;
    int tick = 0;
    int saver = 0;
    int async = 0;
    int bold = 0;
    int force = 0;
    int seg_started = 0;
    int oldstyle = 0;
    int rnd = 0;
    int hi = 0;
    int color = COLOR_GREEN;
    int rainbow = 0;
    int lambda = 0;
    int span = 0;
    int lo = 0;
    int paused = 0;
    int classic = 0;
    int mutate = 0;
    char *msg = "";
    char *ttypath = NULL;

    srand((unsigned)time(NULL));

    opterr = 0;
    while ((opt = getopt(argc, argv, "abBcfhlLnrosmxkVM:u:C:t:")) != -1) {
        switch (opt) {
        case 's':
            saver = 1;
            break;
        case 'a':
            async = 1;
            break;
        case 'b':
            if (bold != 2)
                bold = 1;
            break;
        case 'B':
            bold = 2;
            break;
        case 'L':
            opt_lock = 1;
            if (msg[0] == '\0')
                msg = "Computer locked.";
            break;
        case 'C':
            if (!strcasecmp(optarg, "green"))
                color = COLOR_GREEN;
            else if (!strcasecmp(optarg, "red"))
                color = COLOR_RED;
            else if (!strcasecmp(optarg, "blue"))
                color = COLOR_BLUE;
            else if (!strcasecmp(optarg, "white"))
                color = COLOR_WHITE;
            else if (!strcasecmp(optarg, "yellow"))
                color = COLOR_YELLOW;
            else if (!strcasecmp(optarg, "cyan"))
                color = COLOR_CYAN;
            else if (!strcasecmp(optarg, "magenta"))
                color = COLOR_MAGENTA;
            else if (!strcasecmp(optarg, "black"))
                color = COLOR_BLACK;
            else
                die(" Invalid color selection\n Valid colors are green, red, blue, white, yellow, cyan, magenta and black.\n");
            break;
        case 'c':
            classic = 1;
            break;
        case 'f':
            force = 1;
            break;
        case 'l':
            opt_console = 1;
            break;
        case 'M':
            msg = strdup(optarg);
            break;
        case 'n':
            bold = -1;
            break;
        case 'h':
        case '?':
            print_usage();
            exit(0);
        case 'o':
            oldstyle = 1;
            break;
        case 'u':
            delay = atoi(optarg);
            break;
        case 'x':
            opt_xwindow = 1;
            break;
        case 'V':
            print_version();
            exit(0);
        case 'r':
            rainbow = 1;
            break;
        case 'm':
            lambda = 1;
            break;
        case 'k':
            mutate = 1;
            break;
        case 't':
            ttypath = optarg;
            break;
        }
    }

    if (force && strcmp("linux", getenv("TERM")))
        setenv("TERM", "linux", 1);

    if (ttypath) {
        FILE *f = fopen(ttypath, "r+");
        SCREEN *scr;
        if (!f) {
            fprintf(stderr, "cmatrix: error: '%s' couldn't be opened: %s.\n",
                    ttypath, strerror(errno));
            exit(1);
        }
        scr = newterm(NULL, f, f);
        if (scr == NULL)
            exit(1);
        set_term(scr);
    } else {
        initscr();
    }

    savetty();
    nonl();
    cbreak();
    noecho();
    timeout(0);
    leaveok(stdscr, TRUE);
    curs_set(0);
    signal(SIGINT, on_signal);
    signal(SIGQUIT, on_signal);
    signal(SIGWINCH, on_signal);
    signal(SIGTSTP, on_signal);

    if (opt_console)
        die(" Unable to use both \"setfont\" and \"consolechars\".\n");

    if (has_colors()) {
        start_color();
        if (use_default_colors() != ERR) {
            init_pair(COLOR_BLACK, -1, -1);
            init_pair(COLOR_GREEN, COLOR_GREEN, -1);
            init_pair(COLOR_WHITE, COLOR_WHITE, -1);
            init_pair(COLOR_RED, COLOR_RED, -1);
            init_pair(COLOR_CYAN, COLOR_CYAN, -1);
            init_pair(COLOR_MAGENTA, COLOR_MAGENTA, -1);
            init_pair(COLOR_BLUE, COLOR_BLUE, -1);
            init_pair(COLOR_YELLOW, COLOR_YELLOW, -1);
        } else {
            init_pair(COLOR_BLACK, COLOR_BLACK, COLOR_BLACK);
            init_pair(COLOR_GREEN, COLOR_GREEN, COLOR_BLACK);
            init_pair(COLOR_WHITE, COLOR_WHITE, COLOR_BLACK);
            init_pair(COLOR_RED, COLOR_RED, COLOR_BLACK);
            init_pair(COLOR_CYAN, COLOR_CYAN, COLOR_BLACK);
            init_pair(COLOR_MAGENTA, COLOR_MAGENTA, COLOR_BLACK);
            init_pair(COLOR_BLUE, COLOR_BLUE, COLOR_BLACK);
            init_pair(COLOR_YELLOW, COLOR_YELLOW, COLOR_BLACK);
        }
    }

    if (classic) {
        lo = 12288;
        hi = 12351;
    } else if (opt_console || opt_xwindow) {
        lo = 166;
        hi = 217;
    } else {
        lo = 33;
        hi = 123;
    }
    span = hi - lo;

    setup_grid();

    for (;;) {
        if (pending_signal == SIGINT || pending_signal == SIGQUIT) {
            if (opt_lock != 1)
                finish();
        }
        if (pending_signal == SIGWINCH) {
            handle_resize();
            pending_signal = 0;
        }
        if (pending_signal == SIGTSTP) {
            if (opt_lock != 1)
                finish();
        }

        tick++;
        if (tick > 4)
            tick = 1;

        if ((key = wgetch(stdscr)) != ERR) {
            if (saver == 1) {
                char *buf = NULL;
                size_t n = 0, k;
                do {
                    buf = realloc(buf, n + 1);
                    buf[n++] = (char)key;
                } while ((key = wgetch(stdscr)) != ERR);
                for (k = 0; k < n; k++)
                    ioctl(STDIN_FILENO, TIOCSTI, buf + k);
                free(buf);
                finish();
            } else {
                switch (key) {
                case 'q':
                    if (opt_lock != 1)
                        finish();
                    break;
                case 'a':
                    async = 1 - async;
                    break;
                case 'b':
                    bold = 1;
                    break;
                case 'B':
                    bold = 2;
                    break;
                case 'L':
                    opt_lock = 1;
                    break;
                case 'n':
                    bold = 0;
                    break;
                case '0': case '1': case '2': case '3': case '4':
                case '5': case '6': case '7': case '8': case '9':
                    delay = key - '0';
                    break;
                case '!':
                    color = COLOR_RED;
                    rainbow = 0;
                    break;
                case '@':
                    color = COLOR_GREEN;
                    rainbow = 0;
                    break;
                case '#':
                    color = COLOR_YELLOW;
                    rainbow = 0;
                    break;
                case '$':
                    color = COLOR_BLUE;
                    rainbow = 0;
                    break;
                case '%':
                    color = COLOR_MAGENTA;
                    rainbow = 0;
                    break;
                case 'r':
                    rainbow = 1;
                    break;
                case 'm':
                    lambda = !lambda;
                    break;
                case '^':
                    color = COLOR_CYAN;
                    rainbow = 0;
                    break;
                case '&':
                    color = COLOR_WHITE;
                    rainbow = 0;
                    break;
                case 'p':
                case 'P':
                    paused = paused ? 0 : 1;
                    break;
                }
            }
        }

        for (c = 0; c <= COLS - 1; c += 2) {
            if ((tick > speed[c] || async == 0) && paused == 0) {
                if (oldstyle) {
                    for (r = LINES - 1; r >= 1; r--)
                        grid[r][c].val = grid[r - 1][c].val;
                    rnd = (int)rand() % (span + 8) + lo;

                    if (grid[1][c].val == 0) {
                        grid[0][c].val = 1;
                    } else if (grid[1][c].val == ' ' || grid[1][c].val == -1) {
                        if (gap_left[c] > 0) {
                            grid[0][c].val = ' ';
                            gap_left[c]--;
                        } else {
                            if (((int)rand() % 3) == 1)
                                grid[0][c].val = 0;
                            else
                                grid[0][c].val = (int)rand() % span + lo;
                            gap_left[c] = (int)rand() % LINES + 1;
                        }
                    } else if (rnd > hi && grid[1][c].val != 1) {
                        grid[0][c].val = ' ';
                    } else {
                        grid[0][c].val = (int)rand() % span + lo;
                    }
                } else {
                    int seglen, start;

                    if (grid[0][c].val == -1 && grid[1][c].val == ' ' && gap_left[c] > 0) {
                        grid[0][c].val = -1;
                        gap_left[c]--;
                    } else if (grid[0][c].val == -1 && grid[1][c].val == ' ') {
                        stream_len[c] = (int)rand() % (LINES - 3) + 3;
                        grid[0][c].val = (int)rand() % span + lo;
                        gap_left[c] = (int)rand() % LINES + 1;
                    }

                    r = 0;
                    seglen = 0;
                    seg_started = 0;
                    while (r <= LINES) {
                        while (r <= LINES && (grid[r][c].val == ' ' || grid[r][c].val == -1))
                            r++;
                        if (r > LINES)
                            break;

                        start = r;
                        seglen = 0;
                        while (r <= LINES && (grid[r][c].val != ' ' && grid[r][c].val != -1)) {
                            grid[r][c].is_head = false;
                            if (mutate) {
                                if (rand() % 8 == 0)
                                    grid[r][c].val = (int)rand() % span + lo;
                            }
                            r++;
                            seglen++;
                        }

                        if (r > LINES) {
                            grid[start][c].val = ' ';
                            continue;
                        }

                        grid[r][c].val = (int)rand() % span + lo;
                        grid[r][c].is_head = true;

                        if (seglen > stream_len[c] || seg_started) {
                            grid[start][c].val = ' ';
                            grid[0][c].val = -1;
                        }
                        seg_started = 1;
                        r++;
                    }
                }
            }

            if (!oldstyle) {
                top = 1;
                bottom = LINES;
            } else {
                top = 0;
                bottom = LINES - 1;
            }

            for (r = top; r <= bottom; r++) {
                move(r - top, c);
                if (grid[r][c].val == 0 || (grid[r][c].is_head && !rainbow)) {
                    if (opt_console || opt_xwindow)
                        attron(A_ALTCHARSET);
                    attron(COLOR_PAIR(COLOR_WHITE));
                    if (bold)
                        attron(A_BOLD);
                    if (grid[r][c].val == 0) {
                        if (opt_console || opt_xwindow)
                            addch(183);
                        else
                            addch('&');
                    } else if (grid[r][c].val == -1) {
                        addch(' ');
                    } else {
                        addch(grid[r][c].val);
                    }
                    attroff(COLOR_PAIR(COLOR_WHITE));
                    if (bold)
                        attroff(A_BOLD);
                    if (opt_console || opt_xwindow)
                        attroff(A_ALTCHARSET);
                } else {
                    if (rainbow) {
                        switch (rand() % 6) {
                        case 0: color = COLOR_GREEN; break;
                        case 1: color = COLOR_BLUE; break;
                        case 2: color = COLOR_BLACK; break;
                        case 3: color = COLOR_YELLOW; break;
                        case 4: color = COLOR_CYAN; break;
                        case 5: color = COLOR_MAGENTA; break;
                        }
                    }
                    attron(COLOR_PAIR(color));
                    if (grid[r][c].val == 1) {
                        if (bold)
                            attron(A_BOLD);
                        addch('|');
                        if (bold)
                            attroff(A_BOLD);
                    } else {
                        if (opt_console || opt_xwindow)
                            attron(A_ALTCHARSET);
                        if (bold == 2 || (bold == 1 && grid[r][c].val % 2 == 0))
                            attron(A_BOLD);
                        if (grid[r][c].val == -1) {
                            addch(' ');
                        } else if (lambda && grid[r][c].val != ' ') {
                            addstr("\xce\xbb");
                        } else {
                            addch(grid[r][c].val);
                        }
                        if (bold == 2 || (bold == 1 && grid[r][c].val % 2 == 0))
                            attroff(A_BOLD);
                        if (opt_console || opt_xwindow)
                            attroff(A_ALTCHARSET);
                    }
                    attroff(COLOR_PAIR(color));
                }
            }

            if (msg[0] != '\0') {
                int mrow = LINES / 2;
                int mcol = COLS / 2 - strlen(msg) / 2;
                size_t k;

                move(mrow - 1, mcol - 2);
                for (k = 0; k < strlen(msg) + 4; k++)
                    addch(' ');
                move(mrow, mcol - 2);
                addch(' ');
                addch(' ');
                addstr(msg);
                addch(' ');
                addch(' ');
                move(mrow + 1, mcol - 2);
                for (k = 0; k < strlen(msg) + 4; k++)
                    addch(' ');
            }
        }
        napms(delay * 10);
    }
    finish();
    return 0;
}
